#include "authoring_viewport_fixture.hpp"
#include <carto/d3d12/authoring_viewport.hpp>
#include <iostream>
int main(){try{auto f=fixture();auto source=std::make_shared<const carto::project::ProjectDocument>(std::move(f.document));auto renderer=take(carto::d3d12::AuthoringViewport::create());carto::production::AuthoringViewportRequest r;r.width=3840;r.height=2161;r.temporal.enabled=true;r.temporal.session=1;check(!renderer->render_resident(source,r),"oversized viewport must reject");r.height=2160;auto frame=take(renderer->render_resident(source,r));check(bool(frame.resident_image),"4K native resident texture");check(frame.image.width==3840 && frame.image.height==2160,"4K extent preserved");std::cout<<"4K native temporal resident rendering passed; oversized rejected; "<<frame.device_name<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
